alServiceName": "string" } } }, "match": { "hostname": { "exact": "string", "suffix": "string" }, "metadata": [ { "invert": true|false, "match": { "exact": "string", "prefix": "string", "range": { "end": long, "start": long }, "regex": "string", "suffix": "string" }, "name": "string" } ... ], "port": integer, "serviceName": "string" } }, "http2Route": { "action": { "rewrite": { "hostname": { "defaultTargetHostname": "ENABLED"|"DISABLED" }, "path": { "exact": "string" }, "prefix": { "defaultPrefix": "ENABLED"|"DISABLED", "value": "string" } }, "target": { "port": integer, "virtualService": { "virtualServiceName": "string" } } }, "match": { "headers": [ { "invert": true|false, "match": { "exact": "string", "prefix": "string", "range": { "end": long, "start": long }, "regex": "string", "suffix": "string" }, "name": "string" } ... ], "hostname": { "exact": "string", "suffix": "string" }, "method": "GET"|"HEAD"|"POST"|"PUT"|"DELETE"|"CONNECT"|"OPTIONS"|"TRACE"|"PATCH", "path": { "exact": "string", "regex": "string" }, "port": integer, "prefix": "string", "queryParameters": [ { "match": { "exact": "string" }, "name": "string" } ... ] } }, "httpRoute": { "action": { "rewrite": { "hostname": { "defaultTargetHostname": "ENABLED"|"DISABLED" }, "path": { "exact": "string" }, "prefix": { "defaultPrefix": "ENABLED"|"DISABLED", "value": "string" } }, "target": { "port": integer, "virtualService": { "virtualServiceName": "string" } } }, "match": { "headers": [ { "invert": true|false, "match": { "exact": "string", "prefix": "string", "range": { "end": long, "start": long }, "regex": "string", "suffix": "string" }, "name": "string" } ... ], "hostname": { "exact": "string", "suffix": "string" }, "method": "GET"|"HEAD"|"POST"|"PUT"|"DELETE"|"CONNECT"|"OPTIONS"|"TRACE"|"PATCH", "path": { "exact": "string", "regex": "string" }, "port": integer, "prefix": "string", "queryParameters": [ { "match": { "exact": "string" }, "name": "string" } ... ] } }, "priority": integer }
    /// </summary>
